import React from "react";
import StatusBadge from "./StatusBadge";
import "./ComplaintDetailsModal.css";

// Receives the selected complaint and onClose from the parent.
// Returns null if no complaint is selected (conditional rendering).
function ComplaintDetailsModal({ complaint, onClose }) {
  if (!complaint) return null;

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-content" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h3>Complaint Details</h3>
          <button className="modal-close" onClick={onClose}>
            ✕
          </button>
        </div>
        <div className="modal-body">
          <p><strong>Complaint ID:</strong> {complaint.id}</p>
          <p><strong>Citizen Name:</strong> {complaint.citizenName}</p>
          <p><strong>Issue:</strong> {complaint.issue}</p>
          <p><strong>Department:</strong> {complaint.department}</p>
          <p><strong>Priority:</strong> {complaint.priority}</p>
          <p>
            <strong>Status:</strong> <StatusBadge status={complaint.status} />
          </p>
          <p><strong>Submitted On:</strong> {complaint.submittedOn}</p>
          <p><strong>Description:</strong> {complaint.description}</p>
        </div>
      </div>
    </div>
  );
}

export default ComplaintDetailsModal;
